#!/usr/bin/env python3
"""One test invocation with bounded, incremental, validated screenshot retention."""
import hashlib, json, os, re, signal, struct, subprocess, threading, time, zlib
from pathlib import Path
SELECTIONS={'connections': 'com.music.bitchord.StatusStripEmulatorTest#forYouChipUsesCollectedProfileAndCachedStationWithRealController'}
assert os.environ.get('SPOOL_SHARD') in SELECTIONS
assert os.environ.get('SPOOL_CASE_SELECTORS')==SELECTIONS[os.environ['SPOOL_SHARD']]
OUT=Path('emulator-screens'); DIAG=Path('emulator-diagnostics')
for directory in (OUT,DIAG):
    try:directory.mkdir(exist_ok=True)
    except Exception:pass
ADB=['adb','-s','emulator-5554']; ROOT='/sdcard/Android/data/app.spool.music.dev/files/'
device_gone=threading.Event(); stop=threading.Event(); seen={}; active=set(); lock=threading.Lock(); cancelled=[None]
pending=[]; queued=set(); latest={}
MAX_FILE=12*1024*1024; MAX_RAW=64*1024*1024

def note(message):
    try:
        with (DIAG/'retention.log').open('a') as f:f.write(time.strftime('%FT%TZ',time.gmtime())+' '+message+'\n')
    except Exception:pass

def bounded(args,seconds=8,cap=MAX_FILE,input_bytes=None):
    """Bound time and output, kill the whole diagnostic subprocess group."""
    if args and args[0]=='adb' and device_gone.is_set():raise RuntimeError('device previously confirmed gone; no further device command')
    started=time.monotonic()
    p=subprocess.Popen(args,stdin=subprocess.PIPE if input_bytes is not None else subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
    with lock:active.add(p)
    if input_bytes is not None:
        # Only the fixed short manifest program is written here, never file data.
        try:p.stdin.write(input_bytes);p.stdin.close()
        except BrokenPipeError:pass
    chunks=[]; errors=[]; size=[0]; overflow=threading.Event()
    def consume(pipe,target,limit):
        while True:
            data=pipe.read(65536)
            if not data:break
            size[0]+=len(data)
            if size[0]>limit:overflow.set();break
            target.append(data)
    readers=[threading.Thread(target=consume,args=(p.stdout,chunks,cap),daemon=True),threading.Thread(target=consume,args=(p.stderr,errors,cap),daemon=True)]
    for t in readers:t.start()
    deadline=time.monotonic()+seconds
    while p.poll() is None and time.monotonic()<deadline and not overflow.is_set():time.sleep(.05)
    timed_out=p.poll() is None and not overflow.is_set()
    if p.poll() is None:
        try:os.killpg(p.pid,signal.SIGKILL)
        except ProcessLookupError:pass
    try:p.wait(timeout=2)
    except subprocess.TimeoutExpired:pass
    for t in readers:t.join(timeout=1)
    with lock:active.discard(p)
    output=b''.join(chunks);error=b''.join(errors)
    if args and args[0]=='adb' and ((b'device' in error and b'not found' in error) or b'no devices/emulators found' in error):
        if not device_gone.is_set():device_gone.set();host_snapshot('confirmed-device-gone');note('DEVICE-GONE stop all subsequent device diagnostics')
    if overflow.is_set() or timed_out or p.returncode!=0:
        raise RuntimeError('diagnostic failed '+json.dumps(dict(args=args,rc=p.returncode,timeout=timed_out,overflow=overflow.is_set(),elapsed=round(time.monotonic()-started,3),stdout=repr(output[:1024]),stderr=repr(error[:1024]))))
    return output

def validate(data):
    if len(data)>MAX_FILE or data[:8]!=b'\x89PNG\r\n\x1a\n':raise ValueError('PNG size/signature')
    at=8; ihdr=None; payload=[]; ended=False; has_idat=False
    while at+12<=len(data):
        n=struct.unpack('>I',data[at:at+4])[0];kind=data[at+4:at+8];end=at+8+n
        if n>MAX_FILE or end+4>len(data):raise ValueError('truncated chunk')
        body=data[at+8:end]
        if zlib.crc32(kind+body)&0xffffffff!=struct.unpack('>I',data[end:end+4])[0]:raise ValueError('CRC')
        if ihdr is None:
            if kind!=b'IHDR' or n!=13:raise ValueError('first chunk IHDR required')
            w,h,depth,color,comp,filt,inter=struct.unpack('>IIBBBBB',body)
            channels={0:1,2:3,3:1,4:2,6:4}.get(color)
            if not channels or depth!=8 or comp or filt or inter or not (1<=w<=4096 and 1<=h<=8192):raise ValueError('unsupported IHDR/dimensions')
            stride=w*channels+1;expected=stride*h
            if expected>MAX_RAW:raise ValueError('inflated cap')
            ihdr=(stride,expected)
        elif kind==b'IHDR':raise ValueError('duplicate IHDR')
        if kind==b'IDAT':payload.append(body);has_idat=True
        if kind==b'IEND':
            if n or end+4!=len(data):raise ValueError('bad IEND/trailing bytes')
            ended=True;break
        at=end+4
    if not ended or not has_idat:raise ValueError('missing image/end')
    dec=zlib.decompressobj();raw=dec.decompress(b''.join(payload),ihdr[1]+1)
    if len(raw)!=ihdr[1] or not dec.eof or dec.unused_data or dec.unconsumed_tail:raise ValueError('scanline size/zlib integrity')
    if any(raw[i]>4 for i in range(0,len(raw),ihdr[0])):raise ValueError('invalid scanline filter')

def drain():
    # The app writes flat screenshot PNGs. No tar extraction, links or paths
    # supplied by the device are accepted. Hash manifest detects same-name edits.
    manifest=bounded(ADB+['shell','-T','sh'],
        seconds=10,cap=256*1024,input_bytes=(
            b'cd /sdcard/Android/data/app.spool.music.dev/files || exit 1\n'
            b'for f in *.png; do [ -f "$f" ] && [ ! -L "$f" ] && sha256sum "$f"; done\n'
        )).decode()
    for line in manifest.splitlines():
        match=re.fullmatch(r'([0-9a-f]{64})  ([A-Za-z0-9][A-Za-z0-9_.-]{0,180}\.png)',line)
        if not match:note('invalid manifest record rejected '+repr(line[:300]));continue
        digest,name=match.groups()
        if '..' in name:note('invalid name rejected');continue
        latest[name]=digest
        if seen.get(name)!=digest and name not in queued:pending.append(name);queued.add(name)
    count=0;deadline=time.monotonic()+20;attempts=min(len(pending),20)
    for _ in range(attempts):
        if time.monotonic()>deadline:break
        name=pending.pop(0);queued.discard(name);digest=latest[name]
        if seen.get(name)==digest:continue
        try:
            data=bounded(ADB+['exec-out','cat',ROOT+name],seconds=6)
            if hashlib.sha256(data).hexdigest()!=digest:raise ValueError('in-flight hash mismatch')
            validate(data)
            tmp=OUT/(name+'.part');tmp.write_bytes(data);os.replace(tmp,OUT/name);seen[name]=digest;count+=1
        except Exception as e:
            note('unretained '+name+' '+str(e));pending.append(name);queued.add(name)
    note('promoted '+str(count)+' unresolved '+str(len(pending))+' '+repr(pending))
    return len(pending)

def host_snapshot(label):
    stamp=time.strftime('%FT%TZ',time.gmtime())
    data={'time':stamp,'label':label}
    for file in ['/proc/meminfo','/proc/vmstat','/proc/pressure/memory','/sys/fs/cgroup/memory.current','/sys/fs/cgroup/memory.max','/sys/fs/cgroup/memory.events']:
        try:data[file]=Path(file).read_text()[:32768]
        except Exception as e:data[file]={'unavailable':str(e)}
    try:data['processes']=bounded(['ps','-eo','pid,ppid,rss,%cpu,stat,comm,args'],3,256*1024).decode(errors='replace')
    except Exception as e:data['processes']={'unavailable':str(e)}
    try:
        with (DIAG/'host-snapshots.jsonl').open('a') as f:f.write(json.dumps(data)+'\n')
    except Exception:pass

def monitor():
    while not stop.is_set():
        try:
            host_snapshot('during')
            note('device '+bounded(ADB+['get-state'],3,4096).decode().strip())
        except Exception as e:
            note(str(e))
            if device_gone.is_set():return
            stop.wait(60);continue
        try:drain()
        except Exception as e:note(str(e))
        stop.wait(60)

worker=threading.Thread(target=monitor,daemon=True)
gradle=None

def on_signal(sig,frame):
    cancelled[0]=sig;stop.set()
    if gradle is not None and gradle.poll() is None:
        try:os.killpg(gradle.pid,signal.SIGTERM)
        except ProcessLookupError:pass

for sig in (signal.SIGINT,signal.SIGTERM):signal.signal(sig,on_signal)
status=1
try:
    host_snapshot('before-direct-instrumentation')
    gradle=subprocess.Popen(['python3','/tmp/direct-instrumentation.py'],start_new_session=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1)
    def forward_gradle():
        with (DIAG/'direct-host.log').open('a') as log:
            for line in gradle.stdout:
                print(line,end='',flush=True);log.write(line);log.flush()
    output_thread=threading.Thread(target=forward_gradle,daemon=True);output_thread.start()
    try:worker.start()
    except BaseException as e:note('mirror failed to start '+str(e))
    cancel_deadline=None
    while gradle.poll() is None:
        if cancelled[0] is not None:
            cancel_deadline=cancel_deadline or time.monotonic()+8
            if time.monotonic()>cancel_deadline:
                try:os.killpg(gradle.pid,signal.SIGKILL)
                except ProcessLookupError:pass
        time.sleep(.1)
    output_thread.join(timeout=5)
    status=gradle.returncode
    if device_gone.is_set() and status==0:status=1
finally:
    try:
        # Every cleanup operation is best-effort. None may replace the test status,
        # even when diagnostics cannot write because disk is full.
        try:stop.set()
        except BaseException:pass
        try:worker.join(timeout=28)
        except BaseException:pass
        try:
            with lock:children=list(active)
            for p in children:
                try:os.killpg(p.pid,signal.SIGKILL)
                except BaseException:pass
        except BaseException:pass
        try:worker.join(timeout=4)
        except BaseException:pass
        alive=True
        try:alive=worker.is_alive()
        except BaseException:pass
        if alive:note('mirror worker did not stop; final drain skipped to avoid concurrent drains')
        elif cancelled[0] is None and not device_gone.is_set():
            deadline=time.monotonic()+45
            while time.monotonic()<deadline:
                try:
                    remaining=drain()
                    if remaining==0:break
                except BaseException as e:
                    note('final drain '+str(e));break
            note('final retention unresolved='+str(len(pending))+' budget_expired='+str(time.monotonic()>=deadline)+' names='+repr(pending))
        diagnostics=[('processes',['ps','-eo','pid,ppid,rss,%cpu,stat,comm'])]
        if not device_gone.is_set():diagnostics += [('crash',ADB+['logcat','-b','crash','-d']),('devices',['adb','devices','-l'])]
        for name,args in diagnostics:
            try:(DIAG/(name+'.txt')).write_bytes(bounded(args,4,1024*1024))
            except BaseException as e:note(name+' '+str(e))
        host_snapshot('after-direct-instrumentation')
        try:(DIAG/'test-exit.txt').write_text(str(status)+'\n')
        except BaseException:pass
    except BaseException:pass
raise SystemExit(128+cancelled[0] if cancelled[0] is not None else 128-status if status<0 else status)

