"""Strict AndroidJUnitRunner raw status reconciliation. No inferred test passes."""
import hashlib,json,re
import xml.etree.ElementTree as ET
from pathlib import Path


def reconcile(raw, selectors, destination):
    destination=Path(destination);destination.mkdir(parents=True,exist_ok=True)
    expected=selectors.split(',')
    assert expected and len(expected)==len(set(expected))
    assert all(re.fullmatch(r'com\.music\.bitchord\.StatusStripEmulatorTest#[A-Za-z0-9_]+',x) for x in expected)
    starts=[];finished=[];events=[];fields={};final=[];errors=[]
    for line in raw.decode('utf-8',errors='strict').splitlines():
        if line.startswith('INSTRUMENTATION_STATUS: '):
            key,sep,value=line[len('INSTRUMENTATION_STATUS: '):].partition('=')
            if not sep:errors.append('Malformed status field');continue
            if key in fields:errors.append('Duplicate field in one status block: '+key)
            fields[key]=value
        elif line.startswith('INSTRUMENTATION_STATUS_CODE: '):
            try:
                code=int(line.split(': ',1)[1]);event={**fields,'code':code};events.append(event)
                identity=fields['class']+'#'+fields['test']
                assert fields['id']=='AndroidJUnitRunner'
                assert identity in expected
                assert int(fields['numtests'])==len(expected)
                current=int(fields['current']);assert 1<=current<=len(expected)
                if code==1:
                    assert identity not in starts and identity not in finished
                    assert current==len(starts)+1 and len(starts)==len(finished)
                    starts.append(identity)
                elif code==0:
                    assert starts and starts[-1]==identity and identity not in finished
                    assert current==len(finished)+1
                    assert 'stack' not in fields
                    finished.append(identity)
                else:raise AssertionError('Non-pass terminal status '+str(code))
            except Exception as error:errors.append(type(error).__name__+': '+str(error))
            fields={}
        elif line.startswith('INSTRUMENTATION_CODE: '):
            try:final.append(int(line.split(': ',1)[1]))
            except ValueError:errors.append('Malformed final code')
        elif line.startswith('INSTRUMENTATION_FAILED:') or line.startswith('INSTRUMENTATION_ABORTED:'):
            errors.append(line)
    if fields:errors.append('Unterminated status fields')
    if final!=[-1]:errors.append('Missing/duplicate/non-OK final Android result code')
    if set(starts)!=set(expected) or set(finished)!=set(expected) or len(starts)!=len(expected) or len(finished)!=len(expected):errors.append('Missing/extra/duplicate/zero test records')
    summaries=re.findall(rb'^OK \((\d+) tests?\)\s*$',raw,re.M)
    if summaries!=[str(len(expected)).encode()]:errors.append('Missing/duplicate/wrong runner summary')
    if re.search(rb'FAILURES!!!|Process crashed|INSTRUMENTATION_RESULT: (?:shortMsg|longMsg)=',raw):errors.append('Runner failure/crash evidence')
    report={'provenance':'Derived only from exact AndroidJUnitRunner raw START+PASS status records and final summary, not Gradle XML',
            'raw_sha256':hashlib.sha256(raw).hexdigest(),'expected':expected,'starts':starts,'passes':finished,'events':events,'errors':errors,'pass':not errors}
    (destination/'raw-runner-reconciliation.json').write_text(json.dumps(report,indent=2))
    assert not errors,errors
    suite=ET.Element('testsuite',name='direct-AndroidJUnitRunner',tests=str(len(finished)),failures='0',errors='0',skipped='0')
    properties=ET.SubElement(suite,'properties')
    ET.SubElement(properties,'property',name='raw_sha256',value=report['raw_sha256'])
    ET.SubElement(properties,'property',name='result_provenance',value=report['provenance'])
    for identity in finished:
        cls,name=identity.split('#');ET.SubElement(suite,'testcase',classname=cls,name=name)
    ET.ElementTree(suite).write(destination/'TEST-direct-runner.xml',encoding='utf-8',xml_declaration=True)
    return report

