import groovy.json.JsonOutput

// AGP8.10.1 TaskManager.assetGenTask + TaskFactoryImpl.register(name)
// create these five selected graph anchors without actions. No other task is
// exempted based on a prefix, project, task type or its observed action count.
def sourceProvenAssetAnchors = [
    ':wearos:generateDevDebugAssets',
    ':app:generateDevDebugAssets',
    ':shared:generateDebugAssets',
    ':sharedUi:generateDebugAssets',
    ':app:generateDevDebugAndroidTestAssets',
] as Set

def heavyName = { t ->
    def n = t.name.toLowerCase(java.util.Locale.ROOT)
    n.contains('compile') || n.contains('dex') || n.contains('package') || n.contains('cmake') || n.startsWith('merge') || n.startsWith('strip') || n.startsWith('generate') || n.startsWith('process')
}

gradle.taskGraph.whenReady { graph ->
    // Snapshot after configuration, before adding any guard action. This is
    // original task action evidence, not an inventory of our own doFirst hooks.
    def selected = graph.allTasks.findAll { heavyName(it) }
    def inventory = selected.collect { t ->
        [path: t.path, type: t.class.name,
         originalActionCount: t.actions.size(),
         originalActionTypes: t.actions.collect { it.class.name },
         sourceProvenActionlessAnchor: sourceProvenAssetAnchors.contains(t.path)]
    }
    def evidence = new File(gradle.rootProject.projectDir, 'remaining10-evidence')
    evidence.mkdirs()
    def phase = gradle.rootProject.findProperty('spool.requirePrebuilt') == 'true' ? 'connected' : 'prebuild'
    new File(evidence, "task-action-inventory-${phase}.json").text = JsonOutput.prettyPrint(JsonOutput.toJson(inventory))
    def invalidAnchors = selected.findAll { t ->
        sourceProvenAssetAnchors.contains(t.path) &&
            (!(t instanceof org.gradle.api.DefaultTask) || !t.actions.empty)
    }
    if (!invalidAnchors.empty) throw new GradleException('SOURCE-PROVEN-ANCHOR-HAS-UNEXPECTED-ACTIONS: ' + invalidAnchors.collect { it.path })
    selected.findAll { !sourceProvenAssetAnchors.contains(it.path) }.each { t ->
        // Original heavy action guard, unchanged for every other selected task.
        t.doFirst {
            if (project.findProperty('spool.requirePrebuilt') == 'true') throw new GradleException('UNEXPECTED-HEAVY-ACTION before instrumentation: ' + t.path + '; prebuilt task must be UP-TO-DATE or NO-SOURCE')
        }
    }
}

// Recheck immediately before execution too. Do not attach a task action to an
// actionless anchor, which would itself make the anchor execute every time.
gradle.taskGraph.beforeTask { t ->
    if (sourceProvenAssetAnchors.contains(t.path) &&
        (!(t instanceof org.gradle.api.DefaultTask) || !t.actions.empty)) {
        throw new GradleException('SOURCE-PROVEN-ANCHOR-GAINED-UNEXPECTED-ACTIONS: ' + t.path)
    }
}
